"""Command line entrypoint.

python -m slogen generate --specs slo/specs --out observability/prometheus/rules/slo
python -m slogen generate --specs slo/specs --out ... --check   # CI drift check
python -m slogen validate --specs slo/specs                     # parse + PromQL syntax
"""

from __future__ import annotations

import argparse
import difflib
import sys
from pathlib import Path

import yaml

from . import __version__, rules, spec

HEADER = (
    "# Code generated by slogen {version} from {source}. DO NOT EDIT.\n# Change the spec and run `make slo` instead.\n"
)


class _Dumper(yaml.SafeDumper):
    pass


def _str_presenter(dumper: yaml.SafeDumper, data: str) -> yaml.ScalarNode:
    style = "|" if "\n" in data else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", data, style=style)


_Dumper.add_representer(str, _str_presenter)


def render(service_spec: spec.ServiceSpec, source_label: str) -> str:
    body = yaml.dump(rules.generate(service_spec.slos), Dumper=_Dumper, sort_keys=False, width=120, allow_unicode=True)
    return HEADER.format(version=__version__, source=source_label) + body


def check_promql(expressions: list[str]) -> list[str]:
    """Returns syntax errors. Uses promql-parser when installed (CI and dev do)."""
    try:
        import promql_parser
    except ImportError:
        return []
    errors = []
    for expr in expressions:
        try:
            promql_parser.parse(expr)
        except Exception as exc:  # noqa: BLE001 - parser raises plain ValueError/RuntimeError
            errors.append(f"{exc}\n  in: {expr}")
    return errors


def cmd_generate(args: argparse.Namespace) -> int:
    specs = spec.load_dir(args.specs)
    args.out.mkdir(parents=True, exist_ok=True)
    expected: dict[Path, str] = {}
    for service_spec in specs:
        assert service_spec.source is not None
        # Only the file name: the header must not depend on the caller's cwd.
        label = service_spec.source.name
        expected[args.out / f"{service_spec.service}.yml"] = render(service_spec, label)

    drift = []
    for path, content in expected.items():
        current = path.read_text(encoding="utf-8") if path.exists() else ""
        if current == content:
            continue
        if args.check:
            diff = difflib.unified_diff(
                current.splitlines(keepends=True), content.splitlines(keepends=True), str(path), "generated"
            )
            drift.append("".join(diff))
        else:
            path.write_text(content, encoding="utf-8")
            print(f"wrote {path}")
    stale = sorted(p for p in args.out.glob("*.yml") if p not in expected)
    for path in stale:
        if args.check:
            drift.append(f"stale generated file with no spec: {path}\n")
        else:
            path.unlink()
            print(f"removed {path}")

    if drift:
        sys.stderr.write("".join(drift))
        sys.stderr.write("\nGenerated SLO rules are out of date. Run `make slo` and commit the result.\n")
        return 1
    if args.check:
        print(f"{len(expected)} rule file(s) up to date")
    return 0


def cmd_validate(args: argparse.Namespace) -> int:
    specs = spec.load_dir(args.specs)
    errors = []
    count = 0
    for service_spec in specs:
        exprs = rules.all_expressions(rules.generate(service_spec.slos))
        count += len(exprs)
        errors += check_promql(exprs)
    if errors:
        sys.stderr.write("\n".join(errors) + "\n")
        return 1
    n_slos = sum(len(s.slos) for s in specs)
    print(f"{n_slos} SLO(s) in {len(specs)} file(s) OK, {count} PromQL expressions parsed")
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="slogen", description=__doc__.splitlines()[0])
    parser.add_argument("--version", action="version", version=__version__)
    sub = parser.add_subparsers(dest="command", required=True)

    gen = sub.add_parser("generate", help="write Prometheus rule files from specs")
    gen.add_argument("--specs", type=Path, required=True)
    gen.add_argument("--out", type=Path, required=True)
    gen.add_argument("--check", action="store_true", help="fail if files on disk differ (no writes)")
    gen.set_defaults(func=cmd_generate)

    val = sub.add_parser("validate", help="parse specs and check generated PromQL syntax")
    val.add_argument("--specs", type=Path, required=True)
    val.set_defaults(func=cmd_validate)

    args = parser.parse_args(argv)
    try:
        return args.func(args)
    except spec.SpecError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
